import org.jsoup.nodes.Document;
import org.jsoup.nodes.TextNode;
import org.junit.Assert;
import org.junit.Test;

public class TextNodeTest {

    @Test
    public void createFromEncodedNonEmptyTextTest() {
        String encodedText = "&amp;&lt;&gt;";
        TextNode node = TextNode.createFromEncoded(encodedText, false);
        Assert.assertEquals("Encoded text not preserved", encodedText, node.getWholeText());
    }

    @Test
    public void createFromEncodedEmptyTextTest() {
        String encodedText = "";
        TextNode node = TextNode.createFromEncoded(encodedText, false);
        Assert.assertTrue("Node should be empty", node.isBlank());
    }

    @Test
    public void textNonEmptyTextTest() {
        String text = "hello";
        TextNode textNode = new TextNode(text);
        Assert.assertEquals("Text should be the same", text, textNode.text());
    }

    @Test
    public void textEmptyTextTest() {
        String text = "";
        TextNode node = new TextNode(text);
        Assert.assertTrue("Node should be empty", node.isBlank());
    }

    @Test
    public void nodeNameTest() {
        String text = "hello";
        TextNode node = new TextNode(text);
        Assert.assertEquals("Node name should be #text", "#text", node.nodeName());
    }

    @Test
    public void isBlankNonEmptyTextTest() {
        String text = "hello";
        TextNode node = new TextNode(text);
        Assert.assertFalse("Node should not be empty", node.isBlank());
    }

    @Test
    public void isBlankEmptyTextTest() {
        String text = "";
        TextNode node = new TextNode(text);
        Assert.assertTrue("Node should be empty", node.isBlank());
    }

    @Test(expected = IllegalArgumentException.class)
    public void splitTextNegativeOffsetTest() {
        String text = "hello";
        TextNode node = new TextNode(text);
        node.splitText(-1);
    }

    @Test
    public void splitTextValidOffsetTest() {
        String text = "hello";
        TextNode node = new TextNode(text);
        TextNode newNode = node.splitText(2);
        Assert.assertEquals("Original node should contain the first part of the text", "he", node.getWholeText());
        Assert.assertEquals("New node should contain the second part of the text", "llo", newNode.getWholeText());
    }

    @Test
    public void cloneTest() {
        String text = "hello";
        TextNode node = new TextNode(text);
        TextNode clonedNode = node.clone();
        Assert.assertNotSame("Nodes should not be the same", node, clonedNode);
        Assert.assertEquals("Text should be the same", node.getWholeText(), clonedNode.getWholeText());
    }

} 
